163	// Sends the email for a batch if one is due: there are files the last email did not
164	// cover, and the uploader either said they are done or has gone quiet.
165	async function maybeNotify(batch, now = Date.now()) {
166	  // The owner uploaded it themselves and saw the result on screen.
167	  if (batch.home) return;
168	  if (batch.deletedAt || batch.files.length <= batch.notifiedFiles || notifying.has(batch.id)) return;
169	  const inFlight = uploads.inFlight(batch.id);
170	  const lastActivity = Math.max(Date.parse(batch.updatedAt), ...inFlight.map((id) => uploads.lastWrite(id)));
171	  const done = batch.completedAt && inFlight.length === 0;
172	  if (!done && now - lastActivity < config.idleNotifyMs) return;
173	  if (batch.lastNotifyAttempt && now - Date.parse(batch.lastNotifyAttempt) < 10 * 60_000) return;
174	
175	  notifying.add(batch.id);
176	  const count = batch.files.length;
177	  try {
178	    batches.update(batch, { lastNotifyAttempt: new Date(now).toISOString() });
179	    await notifyBatch(batch, { link: ownerLink(batch), partial: !done });
180	    batches.update(batch, { notifiedFiles: count });
181	    console.log(`batch ${batch.id}: notified (${count} files)`);
182	  } catch (err) {
183	    console.error(`batch ${batch.id}: notification failed, will retry: ${err.message}`);
184	  } finally {
185	    notifying.delete(batch.id);
186	  }
187	}
