189	async function sweep() {
190	  const now = Date.now();
191	  for (const b of batches.all()) {
192	    if (b.deletedAt) {
193	      if (now - Date.parse(b.deletedAt) > 90 * 86_400_000) batches.remove(b);
194	      continue;
195	    }
196	    if (sharesExpired(b, now)) {
197	      console.log(`batch ${b.id}: share links expired`);
198	      deleteBatch(b, 'expired');
199	      continue;
200	    }
201	    // A home upload exists to be shared, and sends no email; one nobody made a link
202	    // for within a day would otherwise sit on the disk with nobody knowing.
203	    if (b.home && !(b.shares ?? []).length && !uploads.inFlight(b.id).length && now - Date.parse(b.updatedAt) > 86_400_000) {
204	      console.log(`batch ${b.id}: home upload never shared`);
205	      deleteBatch(b, 'unshared');
206	      continue;
