280	function streamFile(req, res, file) {
281	  const full = uploads.path(file.id);
282	  let size;
283	  try {
284	    size = fs.statSync(full).size;
285	  } catch {
286	    return html(res, 404, messagePage('Gone', 'That file is no longer here.'));
287	  }
288	  const range = parseRange(req.headers.range, size);
289	  const headers = {
290	    ...securityHeaders,
291	    'content-type': 'application/octet-stream',
292	    'content-disposition': contentDisposition(file.name),
293	    'accept-ranges': 'bytes',
294	    'cache-control': 'no-store',
295	  };
296	  if (range === 'unsatisfiable') {
297	    res.writeHead(416, { ...headers, 'content-range': `bytes */${size}` });
298	    return res.end();
299	  }
300	  const { start, end } = range ?? { start: 0, end: size - 1 };
301	  if (range) headers['content-range'] = `bytes ${start}-${end}/${size}`;
302	  headers['content-length'] = String(size === 0 ? 0 : end - start + 1);
303	  res.writeHead(range ? 206 : 200, headers);
304	  if (req.method === 'HEAD' || size === 0) return res.end();
305	  fs.createReadStream(full, { start, end }).on('error', () => res.destroy()).pipe(res);
306	}
