308	function streamZip(res, batch) {
309	  const names = uniqueNames(batch.files.map((f) => f.name));
310	  const stamp = batch.createdAt.slice(0, 10);
311	  res.writeHead(200, {
312	    ...securityHeaders,
313	    'content-type': 'application/zip',
314	    'content-disposition': contentDisposition(`drop-${stamp}.zip`),
315	    'cache-control': 'no-store',
316	  });
317	  // store: no compression. Most uploads are already compressed, and this keeps the
318	  // zip a plain concatenation that streams at disk speed.
319	  const zip = new ZipArchive({ store: true, forceZip64: batch.files.some((f) => f.size > 0xfffffff0) });
320	  zip.on('error', (err) => {
321	    console.error(`zip for batch ${batch.id} failed: ${err.message}`);
322	    res.destroy();
323	  });
324	  zip.pipe(res);
325	  batch.files.forEach((f, i) => zip.file(uploads.path(f.id), { name: names[i] }));
326	  zip.finalize();
327	}
