507	      await readBody(req).catch(() => {});
508	      deleteBatch(b, 'owner');
509	      return redirect(res, `/b/${b.token}`);
510	    }
511	    if (action === 'share' && m === 'POST') {
512	      const days = await readDays(req);
513	      if (days && b.files.length > 0 && (b.shares ?? []).length < config.maxSharesPerBatch) addShare(b, days);
