521	        batches.update(b, {});
522	        console.log(`batch ${b.id}: share ${s.id} revoked`);
523	      }
524	      return redirect(res, `/b/${b.token}#share`);
525	    }
526	    if (action === 'zip' && m === 'GET') {
527	      batches.update(b, { downloadedAt: new Date().toISOString() });
528	      return streamZip(res, b);
529	    }
530	    const file = r[4] && b.files.find((f) => f.id === r[4]);
531	    if (file && (m === 'GET' || m === 'HEAD')) {
532	      if (m === 'GET' && !req.headers.range) batches.update(b, { downloadedAt: new Date().toISOString() });
