1	// Batches: one per "drop" — the files someone sent in one go. Kept in memory and
2	// written through to one JSON file each, so a restart loses nothing.
3	//
4	// A batch has two identifiers on purpose:
5	//   id     known to the uploader's browser (tus metadata carries it)
6	//   token  known only to the owner (it is in the email link and nowhere else)
7	// so the uploader can add files to their batch but never download or delete them.
8	// Share links add a third kind: download-only tokens with an expiry, which the
9	// owner hands to someone else (batch.shares).
10	
11	import fs from 'node:fs';
12	import path from 'node:path';
13	import crypto from 'node:crypto';
14	
15	export class BatchStore {
16	  constructor(dir) {
17	    this.dir = dir;
18	    this.byId = new Map();
19	    this.byToken = REDACTED Map();
20	    this.shares = new Map();
21	  }
22	
23	  load() {
24	    fs.mkdirSync(this.dir, { recursive: true });
25	    for (const f of fs.readdirSync(this.dir)) {
26	      if (!f.endsWith('.json')) continue;
27	      try {
28	        const b = JSON.parse(fs.readFileSync(path.join(this.dir, f), 'utf8'));
29	        this.index(b);
30	      } catch (err) {
31	        console.error(`skipping unreadable batch ${f}: ${err.message}`);
32	      }
33	    }
34	    return this;
35	  }
36	
37	  create(meta) {
38	    const now = new Date().toISOString();
39	    const b = {
40	      id: crypto.randomUUID(),
41	      token: crypto.randomBytes(24).toString('base64url'),
42	      createdAt: now,
43	      updatedAt: now,
44	      ip: meta.ip ?? null,
45	      // {city, region, country} from Cloudflare's headers, or null.
46	      geo: meta.geo ?? null,
47	      // Uploaded in home mode, i.e. by the owner: only these can be shared from the
48	      // upload page, and their files go when their share links expire.
49	      home: Boolean(meta.home),
50	      userAgent: meta.userAgent ?? null,
51	      files: [],
52	      completedAt: null,
53	      // How many files the last email covered; more than that means another is due.
54	      notifiedFiles: 0,
55	      lastNotifyAttempt: null,
56	      downloadedAt: null,
57	      deletedAt: null,
58	      shares: [],
59	    };
60	    this.save(b);
61	    return b;
62	  }
63	
64	  get(id) {
65	    return this.byId.get(id);
66	  }
67	
68	  byOwnerToken(token) {
69	    return this.byToken.get(token);
70	  }
71	
72	  // The batch and share behind a share token, or nothing.
73	  byShareToken(token) {
74	    return this.shares.get(token);
75	  }
76	
77	  all() {
78	    return [...this.byId.values()];
79	  }
80	
81	  update(b, changes) {
82	    Object.assign(b, changes, { updatedAt: new Date().toISOString() });
83	    this.save(b);
84	    return b;
85	  }
86	
87	  index(b) {
88	    this.byId.set(b.id, b);
89	    this.byToken.set(b.token, b);
90	    for (const s of b.shares ?? []) this.shares.set(s.token, { batch: b, share: s });
91	  }
92	
93	  save(b) {
94	    this.index(b);
95	    const file = path.join(this.dir, `${b.id}.json`);
96	    const tmp = `${file}.${process.pid}.tmp`;
97	    fs.writeFileSync(tmp, JSON.stringify(b, null, 2));
98	    fs.renameSync(tmp, file);
99	  }
100	
101	  remove(b) {
102	    this.byId.delete(b.id);
103	    this.byToken.delete(b.token);
104	    for (const s of b.shares ?? []) this.shares.delete(s.token);
105	    fs.rmSync(path.join(this.dir, `${b.id}.json`), { force: true });
106	  }
107	}
108	
109	export function newShare(days, now = Date.now()) {
110	  return {
111	    id: crypto.randomBytes(6).toString('hex'),
112	    token: crypto.randomBytes(24).toString('base64url'),
113	    createdAt: new Date(now).toISOString(),
114	    expiresAt: new Date(now + days * 86_400_000).toISOString(),
115	    revokedAt: null,
116	    downloadedAt: null,
117	  };
118	}
119	
120	export const shareActive = (s, now = Date.now()) => !s.revokedAt && Date.parse(s.expiresAt) > now;
121	
122	// A home batch is shared to be fetched, not to be kept: once every link that was
123	// not revoked by hand has run out, its files go. A batch whose links were all
124	// revoked stays, for the owner to delete or share again.
125	export function sharesExpired(b, now = Date.now()) {
126	  if (!b.home || b.deletedAt) return false;
127	  const live = (b.shares ?? []).filter((s) => !s.revokedAt);
128	  return live.length > 0 && live.every((s) => Date.parse(s.expiresAt) <= now);
129	}
130	
131	// Every upload tus knows about, finished or not, read from FileStore's sidecar
132	// <id>.json files. This is what the space guard counts.
133	export class UploadIndex {
134	  constructor(dir) {
135	    this.dir = dir;
136	    this.map = new Map();
137	  }
138	
139	  load() {
140	    fs.mkdirSync(this.dir, { recursive: true });
141	    for (const f of fs.readdirSync(this.dir)) {
142	      if (!f.endsWith('.json')) continue;
143	      const id = f.slice(0, -5);
144	      try {
145	        const u = JSON.parse(fs.readFileSync(path.join(this.dir, f), 'utf8'));
146	        const size = Number(u.size);
147	        const done = this.bytesOnDisk(id) >= size;
148	        this.map.set(id, { size, batchId: u.metadata?.batchId ?? null, done, addedAt: Date.now() });
149	      } catch (err) {
150	        console.error(`skipping unreadable upload ${f}: ${err.message}`);
151	      }
152	    }
153	    return this;
154	  }
155	
156	  bytesOnDisk(id) {
157	    try {
158	      return fs.statSync(path.join(this.dir, id)).size;
159	    } catch {
160	      return 0;
161	    }
162	  }
163	
164	  lastWrite(id) {
165	    try {
166	      return fs.statSync(path.join(this.dir, id)).mtimeMs;
167	    } catch {
168	      return 0;
169	    }
170	  }
171	
172	  add(id, size, batchId) {
173	    this.map.set(id, { size, batchId, done: false, addedAt: Date.now() });
174	  }
175	
176	  finish(id) {
177	    const u = this.map.get(id);
178	    if (u) u.done = true;
179	  }
180	
181	  committed() {
182	    let n = 0;
183	    for (const u of this.map.values()) n += u.size;
184	    return n;
185	  }
186	
187	  pending() {
188	    let n = 0;
189	    for (const [id, u] of this.map) if (!u.done) n += Math.max(0, u.size - this.bytesOnDisk(id));
190	    return n;
191	  }
192	
193	  inFlight(batchId) {
194	    return [...this.map].filter(([, u]) => !u.done && u.batchId === batchId).map(([id]) => id);
195	  }
196	
197	  path(id) {
198	    return path.join(this.dir, id);
199	  }
200	
201	  remove(id) {
202	    this.map.delete(id);
203	    fs.rmSync(path.join(this.dir, id), { force: true });
204	    fs.rmSync(path.join(this.dir, `${id}.json`), { force: true });
205	  }
206	}
