1	// "Home mode": the visitor reaches the internet through the same router as this
2	// server, which in practice means the owner, at home or on the home Tailscale exit
3	// node. The server does not know its own public address (it sits behind NAT), so
4	// it asks an outside service what address its requests arrive from and compares
5	// that with the visitor's.
6	//
7	// Nothing runs in the background. A visitor whose address matches the last known
8	// one is home with no lookup at all. A mismatch is either a stranger or a changed
9	// home address, so it triggers a fresh lookup, at most once per recheck interval:
10	// strangers cannot drive more lookups than that. When a lookup fails, the last
11	// known address stays; with none known yet, nobody is home.
12	
13	export function parseTrace(text) {
14	  const m = /^ip=(.+)$/m.exec(text);
15	  return m ? m[1].trim() : null;
16	}
17	
18	export class HomeDetector {
19	  constructor({ lookupUrl, recheckMs, fetchImpl = fetch, now = Date.now }) {
20	    this.lookupUrl = lookupUrl;
21	    this.recheckMs = recheckMs;
22	    this.fetch = fetchImpl;
23	    this.now = now;
24	    this.ip = null;
25	    this.checkedAt = -Infinity;
26	    this.inflight = null;
27	  }
28	
29	  get enabled() {
30	    return Boolean(this.lookupUrl);
31	  }
32	
33	  async isHome(ip) {
34	    if (!this.enabled || !ip) return false;
35	    if (this.ip && ip === this.ip) return true;
36	    if (!this.inflight) {
37	      if (this.now() - this.checkedAt < this.recheckMs) return false;
38	      this.checkedAt = this.now();
39	      this.inflight = this.lookup().finally(() => {
40	        this.inflight = null;
41	      });
42	    }
43	    await this.inflight;
44	    return ip === this.ip;
45	  }
46	
47	  async lookup() {
48	    try {
49	      const res = await this.fetch(this.lookupUrl, { signal: AbortSignal.timeout(3000) });
50	      if (!res.ok) throw new Error(`answered ${res.status}`);
51	      const ip = parseTrace(await res.text());
52	      if (!ip) throw new Error('no ip= line in the answer');
53	      if (ip !== this.ip) console.log(`home address is now ${ip}${this.ip ? ` (was ${this.ip})` : ''}`);
54	      this.ip = ip;
55	    } catch (err) {
56	      console.error(`home address lookup failed, keeping ${this.ip ?? 'none'}: ${err.message}`);
57	    }
58	  }
59	}
