1	// Email goes out through an Apprise API server (POST /notify/<key>), so this app
2	// holds no SMTP credentials. Without APPRISE_URL it only logs.
3	
4	import { config } from './config.js';
5	import { escapeHtml, humanSize, senderLabel } from './util.js';
6	
7	async function send(title, html) {
8	  if (!config.appriseUrl) {
9	    console.log(`[notify:dry-run] ${title}\n${html}`);
10	    return true;
11	  }
12	  const res = await fetch(config.appriseUrl, {
13	    method: 'POST',
14	    headers: { 'content-type': 'application/json' },
15	    body: JSON.stringify({ title, body: html, format: 'html', tag: config.appriseTag }),
16	    signal: AbortSignal.timeout(30_000),
17	  });
18	  if (!res.ok) throw new Error(`apprise answered ${res.status}: ${(await res.text()).slice(0, 200)}`);
19	  return true;
20	}
21	
22	export async function notifyBatch(batch, { link, partial }) {
23	  const files = batch.files;
24	  const total = files.reduce((n, f) => n + f.size, 0);
25	  const isFollowUp = batch.notifiedFiles > 0;
26	  const what = `${files.length} file${files.length === 1 ? '' : 's'} (${humanSize(total)})`;
27	  const title = isFollowUp ? `drop: more files arrived — now ${what}` : `drop: ${what} received`;
28	  const rows = files
29	    .map((f) => `<li>${escapeHtml(f.name)} <span style="color:#888">— ${humanSize(f.size)}</span></li>`)
30	    .join('');
31	  const html = `
32	<p><b>${what}</b> dropped${partial ? ' — the sender left before marking it done, so it may be incomplete' : ''}.</p>
33	<p><a href="${escapeHtml(link)}">${escapeHtml(link)}</a></p>
34	<ul>${rows}</ul>
35	<p style="color:#888">From ${escapeHtml(senderLabel(batch))} · ${escapeHtml(batch.userAgent ?? '')}</p>`;
36	  return send(title, html);
37	}
38	
39	let lastFullNotice = 0;
40	
41	// Told at most twice a day; every refused upload would be a flood otherwise.
42	export async function notifyFull(reason, details) {
43	  if (Date.now() - lastFullNotice < 12 * 3600_000) return;
44	  lastFullNotice = Date.now();
45	  await send(
46	    'drop: refusing uploads — out of room',
47	    `<p>An upload was refused (<b>${escapeHtml(reason)}</b>).</p><pre>${escapeHtml(details)}</pre>
48	<p>Download and delete older drops, or raise MAX_TOTAL / lower MIN_FREE.</p>`,
49	  ).catch((err) => console.error(`full-notice failed: ${err.message}`));
50	}
