1	// Small pure helpers, kept apart so they can be unit-tested without a server.
2	
3	export function humanSize(n) {
4	  if (!Number.isFinite(n)) return '?';
5	  const units = ['B', 'KB', 'MB', 'GB', 'TB'];
6	  let i = 0;
7	  while (n >= 1024 && i < units.length - 1) {
8	    n /= 1024;
9	    i++;
10	  }
11	  return `${n.toFixed(i === 0 || n >= 100 ? 0 : 1)} ${units[i]}`;
12	}
13	
14	// Uploaders choose the name, so it is untrusted: no path parts, no control
15	// characters, bounded length. Never used as a path on disk, only for display and
16	// Content-Disposition.
17	export function cleanFilename(raw) {
18	  let name = String(raw ?? '')
19	    .replace(/[\u0000-\u001f\u007f]/g, '')
20	    .split(/[\\/]/)
21	    .pop()
22	    .trim();
23	  if (!name || name === '.' || name === '..') name = 'file';
24	  if (name.length > 200) {
25	    const dot = name.lastIndexOf('.');
26	    const ext = dot > 0 && name.length - dot <= 16 ? name.slice(dot) : '';
27	    name = name.slice(0, 200 - ext.length) + ext;
28	  }
29	  return name;
30	}
31	
32	// Uppy sends the name as both `filename` and `name`; other tus clients (a curl
33	// script, tus-js-client by hand) often only set `name`.
34	export function uploadName(metadata) {
35	  return cleanFilename(metadata?.filename || metadata?.name);
36	}
37	
38	export function contentDisposition(filename) {
39	  const ascii = filename.replace(/[^\x20-\x7e]/g, '_').replace(/["\\]/g, '_');
40	  return `attachment; filename="${ascii}"; filename*=UTF-8''${encodeURIComponent(filename)}`;
41	}
42	
43	// Single-range "bytes=a-b" only; anything else is served whole, which is what the
44	// spec allows. Returns null for "serve everything", or {start, end} inclusive, or
45	// 'unsatisfiable'.
46	export function parseRange(header, size) {
47	  if (!header) return null;
48	  const m = /^bytes=(\d*)-(\d*)$/.exec(header.trim());
49	  if (!m || (m[1] === '' && m[2] === '')) return null;
50	  let start;
51	  let end;
52	  if (m[1] === '') {
53	    const suffix = Number(m[2]);
54	    if (suffix === 0) return 'unsatisfiable';
55	    start = Math.max(0, size - suffix);
56	    end = size - 1;
57	  } else {
58	    start = Number(m[1]);
59	    end = m[2] === '' ? size - 1 : Math.min(Number(m[2]), size - 1);
60	  }
61	  if (start >= size || start > end) return 'unsatisfiable';
62	  return { start, end };
63	}
64	
65	// Names inside a zip must be unique, or extractors silently overwrite.
66	export function uniqueNames(names) {
67	  const seen = new Map();
68	  return names.map((name) => {
69	    const key = name.toLowerCase();
70	    const n = seen.get(key) ?? 0;
71	    seen.set(key, n + 1);
72	    if (n === 0) return name;
73	    const dot = name.lastIndexOf('.');
74	    return dot > 0 ? `${name.slice(0, dot)} (${n + 1})${name.slice(dot)}` : `${name} (${n + 1})`;
75	  });
76	}
77	
78	// Decides whether a new upload of `size` bytes may start.
79	//   free       bytes free on the volume now
80	//   committed  declared size of every upload stored or in flight
81	//   pending    bytes still to arrive for uploads in flight (already promised)
82	export function spaceVerdict({ size, free, committed, pending }, limits) {
83	  if (!Number.isFinite(size) || size < 0) return { ok: false, reason: 'size-unknown' };
84	  if (size > limits.maxFileSize) return { ok: false, reason: 'file-too-large' };
85	  if (committed + size > limits.maxTotal) return { ok: false, reason: 'quota' };
86	  if (free - pending - size < limits.minFree) return { ok: false, reason: 'disk' };
87	  return { ok: true };
88	}
