90	// Where an address is, as Cloudflare saw it: country from CF-IPCountry, city and
91	// region only when the zone adds visitor location headers. Read once when a send
92	// is created and stored with it, so nothing is looked up later and no visitor
93	// address leaves for a third party.
94	export function geoFromHeaders(headers) {
95	  const get = (h) => {
96	    const v = headers[h];
97	    if (typeof v !== 'string' || !v.trim()) return null;
98	    // Node reads header bytes as latin1; Cloudflare sends UTF-8 (São Paulo).
99	    const utf8 = Buffer.from(v, 'latin1').toString('utf8');
100	    return (utf8.includes('\uFFFD') ? v : utf8).trim().slice(0, 100);
101	  };
102	  const country = get('cf-ipcountry')?.toUpperCase() ?? null;
103	  const geo = {
104	    city: get('cf-ipcity'),
105	    region: get('cf-region'),
106	    country: country && /^[A-Z][A-Z0-9]$/.test(country) && country !== 'XX' ? country : null,
107	  };
108	  return geo.city || geo.region || geo.country ? geo : null;
109	}
110	
111	const countryNames = new Intl.DisplayNames(['en'], { type: 'region', fallback: 'code' });
112	
113	export function countryName(code) {
114	  if (code === 'T1') return 'Tor';
115	  try {
116	    return countryNames.of(code);
117	  } catch {
118	    return code;
119	  }
120	}
121	
122	// "Budapest, Hungary"; null when nothing is known. A region named like its city
123	// (Budapest, Budapest) is said once.
124	export function placeName(geo) {
125	  if (!geo) return null;
126	  const parts = [geo.city, geo.region !== geo.city ? geo.region : null, geo.country ? countryName(geo.country) : null];
127	  return parts.filter(Boolean).join(', ') || null;
128	}
129	
130	// The sender line: "86.59.163.158 (Budapest, Hungary)". Sends from before geo was
131	// recorded show the address alone.
132	export function senderLabel(b) {
133	  const place = placeName(b.geo);
134	  return `${b.ip ?? 'unknown'}${place ? ` (${place})` : ''}`;
135	}
136	
137	export function escapeHtml(s) {
138	  return String(s).replace(
139	    /[&<>"']/g,
140	    (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' })[c],
141	  );
142	}
143	
144	// Fixed-window counter per key. In memory: a restart forgets it, which is fine for
145	// keeping a casual flood off the disk; Cloudflare's rule is the outer limit.
146	export class RateLimiter {
147	  constructor(limit, windowMs) {
148	    this.limit = limit;
149	    this.windowMs = windowMs;
150	    this.hits = new Map();
151	  }
152	  allow(key, now = Date.now()) {
153	    const e = this.hits.get(key);
154	    if (!e || now - e.start >= this.windowMs) {
155	      this.hits.set(key, { start: now, count: 1 });
156	      if (this.hits.size > 10_000) this.prune(now);
157	      return true;
158	    }
159	    e.count++;
160	    return e.count <= this.limit;
161	  }
162	  prune(now) {
163	    for (const [k, e] of this.hits) if (now - e.start >= this.windowMs) this.hits.delete(k);
164	  }
165	}
