55	      target: '#uploader',
56	      inline: true,
57	      width: '100%',
58	      height: 420,
59	      theme: 'dark',
60	      locale: {
61	        strings: {
62	          dropPasteBoth: 'Drop files here — or %{browseFiles} / %{browseFolders}',
63	          dropPasteFiles: 'Drop files here — or %{browseFiles}',
64	          browseFiles: 'browse files',
65	          browseFolders: 'browse folders',
66	          dropHint: 'Release to transmit',
67	          uploadXFiles: { 0: 'Send %{smart_count} file', 1: 'Send %{smart_count} files' },
68	          xFilesSelected: { 0: '%{smart_count} file queued', 1: '%{smart_count} files queued' },
69	          uploading: 'Transmitting',
70	          complete: 'Complete',
71	        },
72	      },
73	      proudlyDisplayPoweredByUppy: false,
74	      fileManagerSelectionType: 'both',
75	      showRemoveButtonAfterComplete: false,
76	      doneButtonHandler: null,
77	      note: null,
78	    })
79	    // The whole page is a drop zone, not only the box.
80	    .use(DropTarget, { target: document.body })
81	    .use(Tus, {
82	      endpoint: '/files/',
83	      chunkSize: CHUNK,
84	      limit: 3,
85	      retryDelays: [0, 1000, 3000, 5000, 10000, 20000, 30000, 60000],
86	      allowedMetaFields: ['batchId', 'name', 'type'],
87	      removeFingerprintOnSuccess: true,
88	      // These answers will not change by retrying: too big, out of room, bad batch.
89	      onShouldRetry(err, attempt, opts, next) {
90	        const status = err?.originalResponse?.getStatus?.();
91	        if ([400, 413, 507].includes(status)) return false;
92	        return next(err);
93	      },
94	    })
