99	  // Every file of one send belongs to one batch, created on the first upload and
100	  // remembered across reloads until the send completes.
101	  uppy.addPreProcessor(async (fileIDs) => {
102	    let batchId = storage.get(BATCH_KEY);
103	    if (!batchId) {
104	      const res = await fetch('/api/batches', { method: 'POST' });
105	      if (!res.ok) {
106	        const msg = (await res.json().catch(() => ({}))).error || 'Upload is not possible right now.';
107	        uppy.info(msg, 'error', 8000);
108	        throw new Error(msg);
109	      }
110	      batchId = (await res.json()).id;
111	      storage.set(BATCH_KEY, batchId);
112	    }
113	    for (const id of fileIDs) {
114	      if (!uppy.getFile(id).meta.batchId) uppy.setFileMeta(id, { batchId });
115	    }
116	  });
117	
118	  uppy.on('complete', async (result) => {
119	    if (!result.successful?.length || result.failed?.length) return;
120	    const batchId = result.successful[0].meta.batchId;
121	    // Even if this call is lost, the server announces the batch on its own once
122	    // it has been quiet for a while.
123	    const done = await fetch(`/api/batches/${batchId}/complete`, { method: 'POST' })
124	      .then((r) => r.json())
125	      .catch(() => ({}));
126	    storage.set(BATCH_KEY, null);
127	    const n = result.successful.length;
128	    $('done-text').textContent = HOME
129	      ? `${n} file${n === 1 ? '' : 's'} received intact.`
130	      : `${n} file${n === 1 ? '' : 's'} received intact. Nothing else to do. You can close this window.`;
131	    $('uploader').hidden = true;
132	    $('done').hidden = false;
133	    if (HOME) showShare(batchId, done.manage);
134	  });
135	
136	  $('again').addEventListener('click', () => {
137	    uppy.clear();
138	    $('done').hidden = true;
139	    $('share').hidden = true;
140	    $('uploader').hidden = false;
141	  });
142	
143	  // A page closed mid-upload would lose the rest; ask first.
144	  window.addEventListener('beforeunload', (ev) => {
145	    const busy = uppy.getFiles().some((f) => f.progress.uploadStarted && !f.progress.uploadComplete);
146	    if (busy) ev.preventDefault();
147	  });
148	}
