1	// The version shown on every page: v1.0.<first 8 of the git commit>.
2	// In the image, the Dockerfile writes the commit to BUILD; running from a checkout,
3	// git answers directly. Anything else is "dev".
4	
5	import fs from 'node:fs';
6	import path from 'node:path';
7	import { execFileSync } from 'node:child_process';
8	import { fileURLToPath } from 'node:url';
9	
10	const root = path.dirname(path.dirname(fileURLToPath(import.meta.url)));
11	const isSha = (s) => /^[0-9a-f]{7,40}$/.test(s);
12	
13	function commit() {
14	  try {
15	    const s = fs.readFileSync(path.join(root, 'BUILD'), 'utf8').trim();
16	    if (isSha(s)) return s.slice(0, 8);
17	  } catch {}
18	  try {
19	    const s = execFileSync('git', ['rev-parse', 'HEAD'], { cwd: root, stdio: ['ignore', 'pipe', 'ignore'] })
20	      .toString()
21	      .trim();
22	    if (isSha(s)) return s.slice(0, 8);
23	  } catch {}
24	  return 'dev';
25	}
26	
27	export const VERSION = `v1.0.${commit()}`;
